# NOTICE: This file was generated by an LLM coding system.
"""Build reviews.csv: a balanced sample of Amazon Movies & TV reviews labelled negative, meh or positive.

    python3 -I collect.py

The source file is 8.4 GB, so this reads CHUNKS byte ranges spread evenly through it
(about 40 MB in all) instead of downloading it, then samples PER_CLASS reviews of each
label with a fixed seed. Standard library only.
"""

import csv
import json
import random
import re
import urllib.request
from pathlib import Path

URL = "https://huggingface.co/datasets/McAuley-Lab/Amazon-Reviews-2023/resolve/main/raw/review_categories/Movies_and_TV.jsonl"
FILE_SIZE = 8_391_445_499
CHUNKS = 10
CHUNK_BYTES = 4_000_000
PER_CLASS = 1500
MAX_CHARS = 2000  # drop very long reviews to keep the file small
SEED = 418
OUT = Path(__file__).resolve().parent / "reviews.csv"

# 1-2 stars is negative, 3 is meh, 4-5 is positive
LABELS = {1: "negative", 2: "negative", 3: "meh", 4: "positive", 5: "positive"}


def fetch_lines(start):
    req = urllib.request.Request(URL, headers={"Range": f"bytes={start}-{start + CHUNK_BYTES - 1}"})
    with urllib.request.urlopen(req) as resp:
        lines = resp.read().decode("utf-8", errors="ignore").split("\n")
    return lines[1:-1]  # the first and last lines are cut off by the range


def clean(text):
    text = re.sub(r"<br\s*/?>", "\n", text)
    return re.sub(r"[ \t]+", " ", text).strip()


def main():
    by_label = {"negative": [], "meh": [], "positive": []}
    for i in range(CHUNKS):
        start = i * (FILE_SIZE - CHUNK_BYTES) // (CHUNKS - 1)
        for line in fetch_lines(start):
            r = json.loads(line)
            text = clean(r["text"])
            if len(text.split()) < 3 or len(text) > MAX_CHARS:
                continue
            by_label[LABELS[int(r["rating"])]].append((int(r["rating"]), text))
        print(f"chunk {i + 1}/{CHUNKS}:", {k: len(v) for k, v in by_label.items()})

    rng = random.Random(SEED)
    rows = []
    for label, reviews in by_label.items():
        rows += [(label, *r) for r in rng.sample(reviews, PER_CLASS)]
    rng.shuffle(rows)

    with open(OUT, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["sentiment", "rating", "text"])
        w.writerows(rows)
    print(f"wrote {len(rows)} rows to {OUT}")


if __name__ == "__main__":
    main()
